def sum_digits(n):
    """
    Returns the sum of all digits in a non-negative integer n.

    :param n: Non-negative integer
    :return: Sum of digits in n
    """
    if n == 0:
        return 0
    else:
        return int(n % 10) + sum_digits(int(n / 10))

